WITH filtered AS (SELECT *, UPPER(device_code) AS device_code_upper, humidity + status_bits AS humidity_plus_status_bits FROM device_readings WHERE reading_ts > DATE '2025-09-01' AND temp_c <= 33) SELECT * FROM (SELECT id, device_code, temp_c, humidity, humidity_plus_status_bits FROM filtered) src UNPIVOT INCLUDE NULLS (metric_value FOR metric_name IN (temp_c AS TEMP_C_VAL, humidity, humidity_plus_status_bits AS HUMIDITY_PLUS_STATUS_BITS_VAL))
